use std::{fmt, io, path::Path};

use zng_txt::{ToTxt, Txt};

/// Connection with a self-extracting executable generated by `cargo zng res --tool sfx`.
pub struct SfxClient {
    sfx_args: Box<[Txt]>,
    manifest: Box<[SfxDataInfo]>,
}
impl SfxClient {
    /// Connect with the "SFX_ARGS" defined server.
    pub fn connect_blocking() -> Result<Self, SfxError> {
        // read args, if is running by sfx
        let args = std::env::var("SFX_ARGS")?;
        let mut sfx_args = vec![];
        for arg in args.split('\n') {
            let arg = arg.trim();
            if arg.is_empty() {
                continue;
            }
            sfx_args.push(Txt::from_str(arg));
        }

        if sfx_args.is_empty() {
            return Err(io::Error::new(io::ErrorKind::InvalidFilename, "SFX_ARGS is empty").into());
        }

        // read manifest
        let out = std::process::Command::new(&sfx_args[0]).env("SFX_GET_MANIFEST", "").output()?;
        if !out.status.success() {
            let err = String::from_utf8_lossy(&out.stderr);
            return Err(io::Error::other(format!("SFX_GET_MANIFEST failed\ncode: {:?}\nstderr:\n{}", out.status, err)).into());
        }
        let stdout = match String::from_utf8(out.stdout) {
            Ok(s) => s,
            Err(e) => return Err(io::Error::new(io::ErrorKind::InvalidData, e).into()),
        };
        let mut manifest = vec![];
        for line in stdout.lines() {
            let mut ok = line.is_empty();
            if let Some((name, len)) = line.rsplit_once(':') {
                if let Ok(len) = len.parse() {
                    ok = true;
                    manifest.push(SfxDataInfo {
                        name: name.to_txt(),
                        exact_len: Some(len),
                    });
                } else if len == "unknown" {
                    ok = true;
                    manifest.push(SfxDataInfo {
                        name: name.to_txt(),
                        exact_len: None,
                    });
                }
            }
            if !ok {
                return Err(io::Error::new(io::ErrorKind::InvalidData, format!("unexpected manifest format, {line:?}")).into());
            }
        }
        manifest.sort_by(|a, b| a.name.cmp(&b.name));
        manifest.dedup_by(|a, b| a.name == b.name);

        Ok(Self {
            sfx_args: sfx_args.into_boxed_slice(),
            manifest: manifest.into_boxed_slice(),
        })
    }

    /// Connect with the "SFX_ARGS" defined server.
    pub async fn connect() -> Result<Self, SfxError> {
        zng_task::wait(Self::connect_blocking).await
    }

    /// The SFX server executable.
    ///
    /// This is the `sfx_args()[0]` value.
    pub fn sfx_exe(&self) -> &Path {
        Path::new(&self.sfx_args[0])
    }

    /// The command line arguments from the SFX executable.
    ///
    /// Note that the sfx process that spawned this process is still running and
    /// replicating stdout/err from this process, impersonating the extracted executable.
    ///
    /// These args are from the user, the [`std::env::args`] are from the sfx tool and are usually empty.
    pub fn sfx_args(&self) -> &[Txt] {
        &self.sfx_args
    }

    /// Info an all data the server can provide.
    ///
    /// List is sorted by name.
    pub fn manifest(&self) -> &[SfxDataInfo] {
        &self.manifest
    }

    /// Get `name` data info it it is in the server manifest.
    pub fn info(&self, name: &str) -> Option<&SfxDataInfo> {
        let i = self.manifest.binary_search_by_key(&name, |n| n.name.as_str()).ok()?;
        Some(&self.manifest[i])
    }

    /// Read raw data.
    ///
    /// The sfx server will automatically decompress/decode data that was marked `compress` on build.
    pub fn read_blocking(&self, name: &str) -> Result<SfxReadBlocking, SfxError> {
        if let Some(info) = self.info(name) {
            let mut r = std::process::Command::new(self.sfx_exe()).env("SFX_GET_DATA", name).spawn()?;
            r.stdin = None;
            Ok(SfxReadBlocking(DefaultSfxReadBlocking {
                server: r,
                exact_len: info.exact_len,
            }))
        } else {
            Err(SfxError::NotFound(Txt::from_str(name)))
        }
    }

    /// Read raw data.
    ///
    /// The sfx server will automatically decompress/decode data that was marked `compress` on build.
    pub async fn read(&self, name: &str) -> Result<SfxRead, SfxError> {
        if let Some(info) = self.info(name) {
            let mut cmd = std::process::Command::new(self.sfx_exe());
            cmd.env("SFX_GET_DATA", name);
            let exact_len = info.exact_len;
            zng_task::wait(move || {
                let mut r = cmd.spawn()?;
                r.stdin = None;
                let inner = SfxReadBlocking(DefaultSfxReadBlocking { server: r, exact_len });
                Ok(SfxRead {
                    inner: zng_task::io::Unblock::new(inner),
                })
            })
            .await
        } else {
            Err(SfxError::NotFound(Txt::from_str(name)))
        }
    }
}

/// Represents a data entry that can be served from a [`SfxClient`].
#[derive(Clone, PartialEq, Debug)]
#[non_exhaustive]
pub struct SfxDataInfo {
    /// Name.
    pub name: Txt,

    /// Exact data length, if it is known.
    ///
    /// This is `None` if the data is decompressing from a custom zstd
    /// file that does not define "contentsize".
    pub exact_len: Option<u64>,
}

/// Read requested data.
///
/// See [`SfxClient::read_blocking`] for more details.
pub struct SfxReadBlocking(DefaultSfxReadBlocking);
impl SfxReadBlocking {
    /// Length not yet read.
    ///
    /// Is `None` if the exact length is not known.
    pub fn exact_len(&self) -> Option<u64> {
        self.0.exact_len
    }
}
struct DefaultSfxReadBlocking {
    // default io::Read::read_to_end impl
    server: std::process::Child,
    exact_len: Option<u64>,
}
impl io::Read for DefaultSfxReadBlocking {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if let Some(s) = &mut self.server.stdout {
            let n = s.read(buf)?;
            if n == 0 {
                self.server.stdout = None;
                self.server.kill()?;
                let status = self.server.wait()?;
                if !status.success() {
                    let mut stderr = String::new();
                    if let Some(mut s) = self.server.stderr.take() {
                        s.read_to_string(&mut stderr)?;
                    }
                    return Err(io::Error::new(
                        io::ErrorKind::ConnectionAborted,
                        format!("server failed\nexit code: {status:?}\nstderr:\n{stderr}"),
                    ));
                }
                if let Some(l) = self.exact_len
                    && l > 0
                {
                    return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "stdout ended before exact length"));
                }
            } else if let Some(l) = &mut self.exact_len {
                let n = n as u64;
                if *l >= n {
                    *l -= n;
                } else {
                    self.server.stdout = None;
                    let _ = self.server.kill();
                    return Err(io::Error::other("stdout longer than expected exact length"));
                }
            }
            Ok(n)
        } else {
            Ok(0)
        }
    }
}
impl io::Read for SfxReadBlocking {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        self.0.read(buf)
    }

    fn read_to_end(&mut self, buf: &mut Vec<u8>) -> io::Result<usize> {
        if let Some(l) = self.0.exact_len {
            let l = l.min(usize::MAX as u64) as usize;
            buf.try_reserve(l)?;
        }
        self.0.read_to_end(buf)
    }

    fn read_to_string(&mut self, buf: &mut String) -> io::Result<usize> {
        if let Some(l) = self.0.exact_len {
            let l = l.min(usize::MAX as u64) as usize;
            buf.try_reserve(l)?;
        }
        self.0.read_to_string(buf)
    }
}
impl Drop for SfxReadBlocking {
    fn drop(&mut self) {
        if let Err(e) = self.0.server.kill() {
            tracing::error!("cannot kill server on drop, {e}");
        }
    }
}

/// Read requested data.
///
/// See [`SfxClient::read`] for more details.
pub struct SfxRead {
    inner: zng_task::io::Unblock<SfxReadBlocking>,
}
impl SfxRead {
    /// Length not yet read.
    ///
    /// Is `None` if the exact length is not known.
    pub async fn exact_len(&mut self) -> Option<u64> {
        self.inner.get_mut().await.0.exact_len
    }

    /// Convert to [`SfxReadBlocking`] that reads the rest of the API.
    pub async fn into_blocking(self) -> SfxReadBlocking {
        self.inner.into_inner().await
    }
}
impl zng_task::io::AsyncRead for SfxRead {
    fn poll_read(self: std::pin::Pin<&mut Self>, cx: &mut std::task::Context<'_>, buf: &mut [u8]) -> std::task::Poll<io::Result<usize>> {
        std::pin::pin!(&mut self.get_mut().inner).poll_read(cx, buf)
    }
}

/// Error connecting or requesting data using [`SfxClient`].
#[derive(Debug)]
#[non_exhaustive]
pub enum SfxError {
    /// Connect error, "SFX_ARGS" not set or invalid.
    Var(std::env::VarError),
    /// IO error attempting to read data.
    Io(io::Error),
    /// Data name not found.
    NotFound(Txt),
}
impl SfxError {
    /// If this error indicates that "SFX_ARGS" env var is not set.
    ///
    /// This can be ok when the current executable is both a setup and the main app.
    pub fn is_no_sfx(&self) -> bool {
        matches!(self, Self::Var(std::env::VarError::NotPresent))
    }
}
impl From<std::env::VarError> for SfxError {
    fn from(var: std::env::VarError) -> Self {
        Self::Var(var)
    }
}
impl From<io::Error> for SfxError {
    fn from(e: io::Error) -> Self {
        Self::Io(e)
    }
}
impl fmt::Display for SfxError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SfxError::Var(e) => fmt::Display::fmt(e, f),
            SfxError::Io(e) => fmt::Display::fmt(e, f),
            SfxError::NotFound(name) => write!(f, "no {name:?} data on the server catalog"),
        }
    }
}
impl std::error::Error for SfxError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            SfxError::Var(e) => Some(e),
            SfxError::Io(e) => Some(e),
            SfxError::NotFound(_) => None,
        }
    }
}
